import XCTest
@testable import KipurseCore

/// t1258 (handbook 0A #10, decision 127/#128): the phone's trust-cap check against the SERVER's own output. The fixture is generated by the
/// gateway (scripts/t1258-trust-caps-fixture.mjs, from trustCapsFor + trustDailyCap) and the gateway test fails if it is stale.
/// Every case must PASS on the phone, and one atomic unit above it must be REFUSED. Phone and server out of step -> this test fails.
final class T1258TrustCapsCrossTests: XCTestCase {
  struct Case: Decodable { let ppm: Int; let ceilingSingle, ceilingDaily, single, dailyStored, dailyInline: String }
  struct File: Decodable { let cases: [Case] }
  func load() throws -> [Case] {
    let u = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("t1258-trust-caps.json.txt")
    return try JSONDecoder().decode(File.self, from: Data(contentsOf: u)).cases
  }
  func msg(_ s: String, _ d: String) -> OwnerTrustMessage {
    OwnerTrustMessage(account: "0x4494cEd7F076c523B3Da8e013E6706AC4d9D3aE6", merchant: "0x" + String(repeating: "11", count: 32), name: "Kipurse Test Shop", epoch: "0",
                      payees: ["0x1768000000000000000000000000000000e9fb00"], signers: [], single: s, daily: d, expiry: "1", nonce: "0x" + String(repeating: "22", count: 32), deadline: "1")
  }
  func testServerOutputAlwaysPassesAndOneMoreIsRefused() throws {
    let cs = try load(); XCTAssertGreaterThanOrEqual(cs.count, 20)
    for c in cs {
      let ceil = (single: Int64(c.ceilingSingle)!, daily: Int64(c.ceilingDaily)!)
      for d in [c.dailyStored, c.dailyInline] {
        XCTAssertEqual(OwnerAsk.trustCapProblems(msg(c.single, d), ceiling: ceil), [], "server output refused: \(c)")
        // one atomic unit above the phone's bound (the owner-signed 0.1%) is always refused; at the live 0.1% fee that is exactly server + 1
        let bound = OwnerAsk.dailyWithFeeHeadroom(ceil.daily)
        XCTAssertLessThanOrEqual(Int64(d)!, bound, "\(c)")
        XCTAssertFalse(OwnerAsk.trustCapProblems(msg(c.single, String(bound + 1)), ceiling: ceil).isEmpty, "above the 0.1% bound accepted: \(c)")
        if c.ppm == 1000 { XCTAssertEqual(Int64(d)!, bound, "at 0.1% the server must use exactly the phone's bound: \(c)") }
      }
      XCTAssertFalse(OwnerAsk.trustCapProblems(msg(String(Int64(c.single)! + 1), c.dailyStored), ceiling: ceil).isEmpty, "single +1 accepted: \(c)")
    }
  }
  func testOwnersRealNumbersAreInTheFixture() throws {
    XCTAssertTrue(try load().contains { $0.ceilingSingle == "1000000000" && $0.ceilingDaily == "1000000000" && $0.dailyInline == "1001000000" && $0.ppm == 1000 })
  }
}
